html,
body,
#app {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
    Arial, 'Noto Sans', sans-serif;
  background: linear-gradient(135deg, #eaf3ff 0%, #f5f9ff 40%, #eef6ff 100%);
  background-attachment: fixed;
  color: #1f2937;
}

* {
  box-sizing: border-box;
}

/* ===== 全局浅色科技蓝主题变量 ===== */
:root {
  --bg-page: #eaf3ff;
  --bg-card: #ffffff;
  --bg-card-hover: #f0f7ff;
  --bg-input: #ffffff;
  --border-color: #dbe7f5;
  --border-color-light: #c9ddf5;
  --text-primary: #1f2937;
  --text-secondary: #4b5563;
  --text-muted: #8a94a6;
  --accent: #3b82f6;
  --accent-hover: #2563eb;
}

/* ===== ElementUI 组件浅色科技蓝主题覆盖 ===== */

/* 卡片 */
.el-card {
  border-radius: 4px;
  background-color: var(--bg-card);
  border-color: var(--border-color);
  color: var(--text-primary);
}
.el-card__header {
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

/* 输入框 */
.el-input__inner,
.el-textarea__inner {
  background-color: var(--bg-input);
  border-color: var(--border-color);
  color: var(--text-primary);
}
.el-input__inner::placeholder,
.el-textarea__inner::placeholder {
  color: var(--text-muted);
}
.el-input__inner:focus,
.el-textarea__inner:focus {
  border-color: var(--accent);
}
.el-input-group__append {
  background-color: var(--bg-input);
  border-color: var(--border-color);
  color: var(--text-secondary);
}
.el-input__prefix,
.el-input__suffix {
  color: var(--text-muted);
}

/* 下拉选择 */
.el-select-dropdown {
  background-color: var(--bg-card);
  border-color: var(--border-color);
}
.el-select-dropdown__item {
  color: var(--text-primary);
}
.el-select-dropdown__item.hover,
.el-select-dropdown__item:hover {
  background-color: var(--bg-card-hover);
}
.el-select-dropdown__item.selected {
  color: var(--accent);
}
.el-select .el-input__inner {
  background-color: var(--bg-input);
  color: var(--text-primary);
}
.el-select__tags .el-tag {
  background-color: var(--bg-card-hover);
  border-color: var(--border-color);
  color: var(--text-primary);
}

/* 弹窗 */
.el-dialog {
  background-color: var(--bg-card);
  border-radius: 12px;
}
.el-dialog__title {
  color: var(--text-primary);
}
.el-dialog__header {
  border-bottom: 1px solid var(--border-color);
}
.el-dialog__body {
  color: var(--text-primary);
}
.el-dialog__footer {
  border-top: 1px solid var(--border-color);
}

/* 表单 */
.el-form-item__label {
  color: var(--text-secondary);
}

/* 表格 */
.el-table {
  background-color: var(--bg-card);
  color: var(--text-primary);
}
.el-table th.el-table__cell {
  background-color: var(--bg-card-hover);
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-color);
}
.el-table td.el-table__cell {
  border-bottom: 1px solid var(--border-color);
}
.el-table tr {
  background-color: var(--bg-card);
}
.el-table--enable-row-hover .el-table__body tr:hover > td.el-table__cell {
  background-color: var(--bg-card-hover);
}
.el-table__empty-block {
  background-color: var(--bg-card);
}
.el-table__empty-text {
  color: var(--text-muted);
}

/* 分页 */
.el-pagination {
  color: var(--text-secondary);
}
.el-pagination.is-background .el-pager li {
  background-color: var(--bg-card-hover);
  color: var(--text-secondary);
}
.el-pagination.is-background .el-pager li:not(.disabled):hover {
  color: var(--accent);
}
.el-pagination.is-background .el-pager li.active {
  background-color: var(--accent);
  color: #fff;
}
.el-pagination.is-background .btn-prev,
.el-pagination.is-background .btn-next {
  background-color: var(--bg-card-hover);
  color: var(--text-secondary);
}

/* 标签 */
.el-tag {
  background-color: var(--bg-card-hover);
  border-color: var(--border-color);
  color: var(--text-secondary);
}

/* 空状态 */
.el-empty__description p {
  color: var(--text-muted);
}

/* 消息提示 */
.el-message {
  background-color: var(--bg-card);
  border-color: var(--border-color);
  color: var(--text-primary);
}

/* 确认框 */
.el-message-box {
  background-color: var(--bg-card);
  border-color: var(--border-color);
}
.el-message-box__title {
  color: var(--text-primary);
}
.el-message-box__content {
  color: var(--text-secondary);
}

/* 加载遮罩 */
.el-loading-mask {
  background-color: rgba(234, 243, 255, 0.7);
}

/* 下拉菜单 */
.el-dropdown-menu {
  background-color: var(--bg-card);
  border-color: var(--border-color);
}
.el-dropdown-menu__item {
  color: var(--text-primary);
}
.el-dropdown-menu__item:not(.is-disabled):hover {
  background-color: var(--bg-card-hover);
  color: var(--accent);
}

/* 开关 */
.el-switch__label {
  color: var(--text-secondary);
}
.el-switch__label.is-active {
  color: var(--text-primary);
}

/* 滚动条 */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg-page);
}
::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--border-color-light);
}

import Vue from 'vue'
import Router from 'vue-router'

Vue.use(Router)

const Dashboard = () => import('@/views/Dashboard.vue')
const TablePage = () => import('@/views/TablePage.vue')
const CommandMarket = () => import('@/views/CommandMarket.vue')
const NoCodeBuilder = () => import('@/views/NoCodeBuilder.vue')
const NoCodePreview = () => import('@/views/NoCodePreview.vue')
const DevEditor = () => import('@/views/DevEditor.vue')
const ClawWorkbench = () => import('@/views/ClawWorkbench.vue')

const FootballGoalsChart = () => import('@/views/FootballGoalsChart.vue')
const BasketballChart = () => import('@/views/BasketballChart.vue')
const BadmintonChart = () => import('@/views/BadmintonChart.vue')
const TodayStockRecommendation = () => import('@/views/TodayStockRecommendation.vue')
const FuturesPrediction = () => import('@/views/FuturesPrediction.vue')
const CommandDetail = () => import('@/views/CommandDetail.vue')
const OrchestrationBuilder = () => import('@/views/OrchestrationBuilder.vue')
const LongTermMemory = () => import('@/views/LongTermMemory.vue')
export default new Router({
  mode: 'history',
  routes: [
    {
      path: '/',
      redirect: '/dashboard'
    },
    {
      path: '/dashboard',
      component: Dashboard,
      meta: { title: '仪表盘' }
    },
    {
      path: '/table',
      component: TablePage,
      meta: { title: '表格示例' }
    },
    {
      path: '/command-market',
      component: CommandMarket,
      meta: { title: '指令市场' }
    },
    {
      path: '/no-code',
      component: NoCodeBuilder,
      meta: { title: '无代码开发' }
    },
    {
      path: '/no-code/preview/:id',
      component: NoCodePreview,
      meta: { title: '页面预览' }
    },
    {
      path: '/dev/editor',
      component: DevEditor,
      meta: { title: '云编译器（内部）' }
    },
    {
      path: '/claw',
      component: ClawWorkbench,
      meta: { title: 'Claw 工作台' }
    },
    {
      path: '/football-goals-chart',
      component: FootballGoalsChart,
      meta: { title: '足球进球统计' }
    },

    {
      path: '/basketball-chart',
      component: BasketballChart,
      meta: { title: '篮球统计' }
    },
    {
      path: '/badminton-chart',
      component: BadmintonChart,
      meta: { title: '羽毛球数据统计' }
    },
    {
      path: '/today-stock-recommendation',
      component: TodayStockRecommendation,
      meta: { title: '今日股票推荐' }
    },
    {
      path: '/futures-prediction',
      component: FuturesPrediction,
      meta: { title: '期货预测' }
    },
    {
      path: '/command/detail/:id',
      component: CommandDetail,
      meta: { title: '指令详情' }
    },
    {
      path: '/orchestration',
      component: OrchestrationBuilder,
      meta: { title: '编排' }
    },
    {
      path: '/long-term-memory',
      component: LongTermMemory,
      meta: { title: '长期记忆' }
    }
  ]
})

